const { content, deadlineAt, assigneeEmail, linkedObject, linkedRecordId } = $.input;

if (!content) throw new Error('content is required');

const data = {
  content: content,
  format: 'plaintext',
  deadline_at: deadlineAt || null,
  is_completed: false,
  linked_records: [],
  assignees: []
};

if (linkedObject && linkedRecordId) {
  data.linked_records.push({
    target_object: linkedObject,
    target_record_id: linkedRecordId
  });
}

if (assigneeEmail) {
  data.assignees.push({
    workspace_member_email_address: assigneeEmail
  });
}

return { data };

const resp = $.steps.createTask.response || {};
const data = resp.data || {};
const id = data.id || {};

return {
  taskId: id.task_id || '',
  content: data.content_plaintext || $.input.content,
  deadlineAt: data.deadline_at || null,
  isCompleted: data.is_completed || false,
  createdAt: data.created_at || '',
  summary: id.task_id
    ? `Created task "${$.input.content.substring(0, 60)}" (${id.task_id})`
    : 'Failed to create task'
};
